diagram:
graph TD;
    A[OSI Model] --> B[7. Application];
    B --> C[6. Presentation];
    C --> D[5. Session];
    D --> E[4. Transport];
    E --> F[3. Network];
    F --> G[2. Data Link];
    G --> H[1. Physical];

    I[TCP/IP Model] --> J[5. Application];
    J --> K[4. Transport];
    K --> L[3. Internet];
    L --> M[2. Network Access];
    M --> N[1. Physical];

graph TD;
    A[Original Signal] --> B{Transmission Medium};
    B -- Loss of energy (strength decreases) --> C[Attenuation];
    B -- Change in signal shape (different propagation speeds) --> D[Distortion];
    B -- Addition of unwanted signals --> E[Noise];
    B -- Impaired Signal --> F[Received Signal];

graph TD;
    subgraph Data Link Layer
        LLC[Logical Link Control (LLC)] -- Handles Flow/Error Control --> NL[Network Layer];
        MAC[Media Access Control (MAC)] -- Manages Medium Access & Addressing --> PL[Physical Layer];
    end

    subgraph Stop-and-Wait ARQ
        Sender[Sender] -->|Send Frame| Receiver[Receiver];
        Receiver -- ACK (if correct) --> Sender;
        Receiver -- NACK (if damaged) --> Sender;
        Sender -- Timeout -->|Retransmit Frame| Sender;
    end

graph TD;
    C1[Client 1] -->|Request Service| S[Server];
    C2[Client 2] -->|Request Service| S;
    C3[Client 3] -->|Request Service| S;
    S --|Provide Service| C1;
    S --|Provide Service| C2;
    S --|Provide Service| C3;
